window.kbPageData["views/entry/k-80e78a1d0d350c3b"] = {"key":"entry/k-80e78a1d0d350c3b","state":{"route":"entry/k-80e78a1d0d350c3b"},"node":{"id":"k-80e78a1d0d350c3b","mode":"k","title":"育儿补贴制度","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#45"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["employment","modern"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["公共管理","政治理论"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["政治理论专项","时政"]},"eventTags":[{"year":2025,"title":"育儿补贴制度","slug":"bc62a742b45a"}],"directorySummary":"育儿补贴制度是通过向符合条件的家庭提供补贴来加强养育保障的制度安排。2025年《提振消费专项行动方案》提出研究建立这一制度。","review":{"definition":"育儿补贴制度是通过向符合条件的家庭提供补贴来加强养育保障的制度安排。2025年《提振消费专项行动方案》提出研究建立这一制度。","explanation":"《方案》将这项任务列在消费能力保障支持行动的“加大生育养育保障力度”之下，因此⑤的政策归属正确。“研究建立”是该方案在此处使用的政策措辞。","references":[],"evidence":"研究建立育儿补贴制度","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"dacac9bacd101e70","label":"育儿补贴制度","topic":"年度政府工作","category":"时政","text":"4.育儿补贴制度\n（一）补贴对象。从 2025 年 1 月 1 日起，对符合法律法规规定生育的 3 周岁以下婴幼\n儿发放补贴，至其年满 3 周岁。\n（二）补贴标准。育儿补贴按年发放，现阶段国家基础标准为每孩每年 3600 元。其中，\n对 2025 年 1 月 1 日之前出生、不满 3 周岁的婴幼儿，按应补贴月数折算计发补贴。对按照\n育儿补贴制度规定发放的育儿补贴免征个人所得税。在最低生活保障对象、特困人员等救助\n对象认定时，育儿补贴不计入家庭或个人收入。\n——《育儿补贴制度实施方案》","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":3,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#45":{"paper":"政治理论必刷100题","n":45,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",14],"asrc":["国省考政治理论必刷100题.pdf",60],"card":"6365c94ac9ad29de0b4faff0","links":[{"id":"k-80e78a1d0d350c3b","role":"直接考查","why":"研究建立育儿补贴制度属于该行动的生育养育保障措施。"}]}},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"},{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-80e78a1d0d350c3b":[["政治理论必刷100题#45"]]}};
